WITH filtered_shipments AS (SELECT *, DATE_TRUNC('MONTH', shipped_date) AS shipped_date_period FROM shipments WHERE carrier IN ('FedEx', 'DHL') AND shipped_date BETWEEN '2025-01-31' AND '2025-10-06' AND order_id = 15), agg AS (SELECT status, carrier, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values FROM filtered_shipments GROUP BY status, carrier) SELECT * FROM agg
